  bytes  bigint
  sha256  text  not null
  page  integer  not null  default 1
  variant  text  not null  default 'original'::text
  captured_at  timestamp with time zone
  uploaded_by  uuid
  created_at  timestamp with time zone  not null  default now()
  derived_from  uuid
  constraint documents_bytes_check: CHECK (((bytes IS NULL) OR (bytes > 0)))
  constraint documents_content_type_check: CHECK ((content_type = ANY (ARRAY['application/pdf'::text, 'image/jpeg'::text, 'image/png'::text, 'image/webp'::text, 'image/heic'::text])))
  constraint documents_content_type_not_null: NOT NULL content_type
  constraint documents_created_at_not_null: NOT NULL created_at
  constraint documents_derived_from_fkey: FOREIGN KEY (derived_from) REFERENCES documents(id) ON DELETE RESTRICT
  constraint documents_id_not_null: NOT NULL id
  constraint documents_kind_check: CHECK ((kind = ANY (ARRAY['cdl'::text, 'medical_card'::text, 'endorsement'::text, 'hazmat_training'::text, 'twic'::text, 'registration'::text, 'annual_inspection'::text, 'insurance'::text, 'ifta'::text, 'irp'::text, 'phmsa_registration'::text, 'hazmat_safety_permit'::text, 'security_plan'::text, 'financial_responsibility'::text, 'operating_authority'::text, 'employment_application'::text, 'mvr'::text, 'annual_mvr_review'::text, 'road_test'::text, 'cdl_equivalency'::text, 'previous_employer_inquiry'::text, 'previous_employer_response'::text, 'clearinghouse_full'::text, 'clearinghouse_limited'::text, 'eldt'::text, 'spe_certificate'::text, 'medical_registry_verification'::text, 'drug_test'::text, 'alcohol_test'::text, 'accident'::text, 'psp_report'::text, 'return_to_duty'::text, 'other'::text])))
  constraint documents_kind_not_null: NOT NULL kind
  constraint documents_org_id_fkey: FOREIGN KEY (org_id) REFERENCES organizations(id) ON DELETE CASCADE
  constraint documents_org_id_not_null: NOT NULL org_id
  constraint documents_page_check: CHECK ((page >= 1))
  constraint documents_page_not_null: NOT NULL page
  constraint documents_pkey: PRIMARY KEY (id)
  constraint documents_sha256_not_null: NOT NULL sha256
  constraint documents_storage_path_not_null: NOT NULL storage_path
  constraint documents_subject_id_not_null: NOT NULL subject_id
  constraint documents_subject_type_check: CHECK ((subject_type = ANY (ARRAY['driver'::text, 'tractor'::text, 'trailer'::text, 'load'::text, 'organization'::text])))
  constraint documents_subject_type_not_null: NOT NULL subject_type
  constraint documents_uploaded_by_fkey: FOREIGN KEY (uploaded_by) REFERENCES auth.users(id) ON DELETE SET NULL
  constraint documents_variant_check: CHECK ((variant = ANY (ARRAY['original'::text, 'normalized'::text, 'thumb'::text])))
  constraint documents_variant_not_null: NOT NULL variant
  index: unique index documents_pkey on public.documents using btree (id)
  index: index idx_documents_derived_from on public.documents using btree (derived_from) where (derived_from is not null)
  index: index idx_documents_org_kind on public.documents using btree (org_id, kind, subject_type)
  index: index idx_documents_subject on public.documents using btree (org_id, subject_type, subject_id, created_at desc)
  policy documents_driver_scope [RESTRICTIVE/SELECT] roles=["public"] using=((auth_role() <> 'driver'::text) OR ((subject_type = 'driver'::text) AND (subject_id = auth_driver_id()))) check=-
  policy documents_insert [PERMISSIVE/INSERT] roles=["public"] using=- check=((org_id = auth_org_id()) AND (auth_role() = ANY (ARRAY['admin'::text, 'fleet_manager'::text, 'safety_manager'::text])))
  policy documents_restricted_investigation [RESTRICTIVE/SELECT] roles=["public"] using=((kind <> ALL (ARRAY['previous_employer_inquiry'::text, 'previous_employer_response'::text, 'psp_report'::text])) OR (auth_role() = ANY (ARRAY['admin'::text, 'safety_manager'::text, 'recruiter'::text]))) check=-
  policy documents_restricted_testing [RESTRICTIVE/SELECT] roles=["public"] using=((kind <> ALL (ARRAY['drug_test'::text, 'alcohol_test'::text, 'clearinghouse_full'::text, 'clearinghouse_limited'::text, 'return_to_duty'::text])) OR (auth_role() = ANY (ARRAY['admin'::text, 'safety_manager'::text]))) check=-
  policy documents_select [PERMISSIVE/SELECT] roles=["public"] using=(org_id = auth_org_id()) check=-
  trigger: create trigger trg_documents_org_immutable before update on public.documents for each row execute function forbid_org_change()

-- ============================================================================
-- table dq_exports  [RLS]
--   Ledger of every driver-qualification export (DQ-BINDER-PLAN D-BD9): who exported which drivers,
--   as at what date, and what came out. Service-role writes only; no UPDATE/DELETE policy. The
--   row
--   outlives the bytes — the seven-day sweep clears storage_path and stamps purged_at.
  id  uuid  not null  default gen_random_uuid()
  org_id  uuid  not null
  kind  text  not null
  driver_ids  ARRAY  not null
  requirement_key  text
  document_id  uuid
  as_at  date  not null
  status  text  not null  default 'queued'::text
  job_id  uuid
  storage_path  text
  bytes  bigint
  pages  integer
  drivers_count  integer
  documents_count  integer
  gaps_count  integer
  error  text
  requested_by  uuid
  created_at  timestamp with time zone  not null  default now()
  completed_at  timestamp with time zone
  expires_at  timestamp with time zone
  purged_at  timestamp with time zone
  include_restricted  boolean  not null  default false
  constraint dq_exports_as_at_not_null: NOT NULL as_at
  constraint dq_exports_bytes_check: CHECK (((bytes IS NULL) OR (bytes > 0)))
  constraint dq_exports_created_at_not_null: NOT NULL created_at
  constraint dq_exports_document_id_fkey: FOREIGN KEY (document_id) REFERENCES documents(id) ON DELETE SET NULL
  constraint dq_exports_documents_count_check: CHECK (((documents_count IS NULL) OR (documents_count >= 0)))
  constraint dq_exports_driver_ids_not_null: NOT NULL driver_ids
  constraint dq_exports_drivers_count_check: CHECK (((drivers_count IS NULL) OR (drivers_count >= 0)))
  constraint dq_exports_gaps_count_check: CHECK (((gaps_count IS NULL) OR (gaps_count >= 0)))
  constraint dq_exports_id_not_null: NOT NULL id
  constraint dq_exports_include_restricted_not_null: NOT NULL include_restricted
  constraint dq_exports_kind_check: CHECK ((kind = ANY (ARRAY['binder'::text, 'document'::text])))
  constraint dq_exports_kind_not_null: NOT NULL kind
  constraint dq_exports_org_id_fkey: FOREIGN KEY (org_id) REFERENCES organizations(id) ON DELETE CASCADE
  constraint dq_exports_org_id_not_null: NOT NULL org_id
  constraint dq_exports_pages_check: CHECK (((pages IS NULL) OR (pages > 0)))
  constraint dq_exports_pkey: PRIMARY KEY (id)
  constraint dq_exports_requested_by_fkey: FOREIGN KEY (requested_by) REFERENCES auth.users(id) ON DELETE SET NULL
  constraint dq_exports_sample_size: CHECK (((cardinality(driver_ids) >= 1) AND (cardinality(driver_ids) <= 25)))
  constraint dq_exports_shape: CHECK (
CASE
    WHEN (kind = 'document'::text) THEN ((cardinality(driver_ids) = 1) AND (requirement_key IS NOT NULL))
    ELSE ((requirement_key IS NULL) AND (document_id IS NULL))
END)
  constraint dq_exports_status_check: CHECK ((status = ANY (ARRAY['queued'::text, 'running'::text, 'done'::text, 'failed'::text])))
  constraint dq_exports_status_not_null: NOT NULL status
  index: unique index dq_exports_pkey on public.dq_exports using btree (id)
  index: index idx_dq_exports_org_created on public.dq_exports using btree (org_id, created_at desc)
  index: index idx_dq_exports_sweep on public.dq_exports using btree (expires_at) where ((storage_path is not null) and (purged_at is null))
  policy dq_exports_select [PERMISSIVE/SELECT] roles=["public"] using=((org_id = auth_org_id()) AND (auth_role() = ANY (ARRAY['admin'::text, 'fleet_manager'::text, 'safety_manager'::text, 'auditor'::text]))) check=-
  trigger: create trigger trg_dq_exports_org_immutable before update on public.dq_exports for each row execute function forbid_org_change()

