-- table driver_authorizations  [RLS]
--   The driver's written disclosure + authorization for each screening purpose (HIRING-PLAN.md H1).
--   One row IS one document, because FCRA §604(b)(2) requires the disclosure to stand alone.
--   Append-only;
--   a revocation is a row whose `revokes` names the grant. Blocks every screening call.
  id  uuid  not null  default gen_random_uuid()
  org_id  uuid  not null
  driver_id  uuid  not null
  purpose  text  not null
  disclosure_version  text  not null
  disclosure_text  text  not null
  method  text  not null
  signed_name  text  not null
  intent_statement  text  not null
  esign_consent_at  timestamp with time zone
  accepted_at  timestamp with time zone  not null  default now()
  accepted_ip  inet
  accepted_user_agent  text
  evidence_document_id  uuid
  recorded_by  uuid
  revokes  uuid
  revoke_reason  text
  created_at  timestamp with time zone  not null  default now()
  invitation_id  uuid
  constraint driver_authorizations_accepted_at_not_null: NOT NULL accepted_at
  constraint driver_authorizations_created_at_not_null: NOT NULL created_at
  constraint driver_authorizations_disclosure_text_not_null: NOT NULL disclosure_text
  constraint driver_authorizations_disclosure_version_not_null: NOT NULL disclosure_version
  constraint driver_authorizations_driver_id_fkey: FOREIGN KEY (driver_id) REFERENCES drivers(id) ON DELETE CASCADE
  constraint driver_authorizations_driver_id_not_null: NOT NULL driver_id
  constraint driver_authorizations_id_not_null: NOT NULL id
  constraint driver_authorizations_intent_statement_not_null: NOT NULL intent_statement
  constraint driver_authorizations_invitation_id_fkey: FOREIGN KEY (invitation_id) REFERENCES application_invitations(id) ON DELETE SET NULL
  constraint driver_authorizations_method_check: CHECK ((method = ANY (ARRAY['esign'::text, 'wet_signature'::text, 'verbal_documented'::text])))
  constraint driver_authorizations_method_not_null: NOT NULL method
  constraint driver_authorizations_org_id_fkey: FOREIGN KEY (org_id) REFERENCES organizations(id) ON DELETE CASCADE
  constraint driver_authorizations_org_id_not_null: NOT NULL org_id
  constraint driver_authorizations_pkey: PRIMARY KEY (id)
  constraint driver_authorizations_purpose_check: CHECK ((purpose = ANY (ARRAY['fcra_disclosure'::text, 'psp'::text, 'previous_employer'::text, 'clearinghouse'::text, 'drug_alcohol'::text])))
  constraint driver_authorizations_purpose_not_null: NOT NULL purpose
  constraint driver_authorizations_recorded_by_fkey: FOREIGN KEY (recorded_by) REFERENCES auth.users(id) ON DELETE SET NULL
  constraint driver_authorizations_revocation_shape: CHECK (((revokes IS NULL) OR (revoke_reason IS NOT NULL)))
  constraint driver_authorizations_revokes_fkey: FOREIGN KEY (revokes) REFERENCES driver_authorizations(id) ON DELETE RESTRICT
  constraint driver_authorizations_signed_name_not_null: NOT NULL signed_name
  index: unique index driver_authorizations_pkey on public.driver_authorizations using btree (id)
  index: index idx_driver_authorizations_live on public.driver_authorizations using btree (org_id, driver_id, purpose, accepted_at desc)
  index: index idx_driver_authorizations_revokes on public.driver_authorizations using btree (revokes) where (revokes is not null)
  index: unique index uq_driver_authorizations_invitation_purpose on public.driver_authorizations using btree (invitation_id, purpose) where ((invitation_id is not null) and (revokes is null))
  policy driver_authorizations_driver_scope [RESTRICTIVE/SELECT] roles=["public"] using=((auth_role() <> 'driver'::text) OR (driver_id = auth_driver_id())) check=-
  policy driver_authorizations_insert [PERMISSIVE/INSERT] roles=["public"] using=- check=((org_id = auth_org_id()) AND (auth_role() = ANY (ARRAY['admin'::text, 'fleet_manager'::text, 'safety_manager'::text, 'recruiter'::text])))
