  trigger: create trigger trg_driver_vehicle_assignments_org_immutable before update on public.driver_vehicle_assignments for each row execute function forbid_org_change()

-- ============================================================================
-- table driver_write_counters  [RLS]
--   Per-driver daily write counts behind D57's business caps. Service-role only: RLS denies all
--   client access by design. Rows are safe to purge after ~90 days.
  org_id  uuid  not null
  user_id  uuid  not null
  bucket  text  not null
  day  date  not null
  count  integer  not null  default 0
  updated_at  timestamp with time zone  not null  default now()
  constraint driver_write_counters_bucket_check: CHECK ((bucket = ANY (ARRAY['shift'::text, 'load_action'::text, 'stop_capture'::text, 'message'::text])))
  constraint driver_write_counters_bucket_not_null: NOT NULL bucket
  constraint driver_write_counters_count_not_null: NOT NULL count
  constraint driver_write_counters_day_not_null: NOT NULL day
  constraint driver_write_counters_org_id_fkey: FOREIGN KEY (org_id) REFERENCES organizations(id) ON DELETE CASCADE
  constraint driver_write_counters_org_id_not_null: NOT NULL org_id
  constraint driver_write_counters_pkey: PRIMARY KEY (user_id, bucket, day)
  constraint driver_write_counters_updated_at_not_null: NOT NULL updated_at
  constraint driver_write_counters_user_id_fkey: FOREIGN KEY (user_id) REFERENCES auth.users(id) ON DELETE CASCADE
  constraint driver_write_counters_user_id_not_null: NOT NULL user_id
  index: unique index driver_write_counters_pkey on public.driver_write_counters using btree (user_id, bucket, day)
  index: index idx_driver_write_counters_day on public.driver_write_counters using btree (day)
  trigger: create trigger trg_driver_write_counters_org_immutable before update on public.driver_write_counters for each row execute function forbid_org_change()

-- ============================================================================
-- table drivers  [RLS]
--   module=roster; layer=core (0265, D-SEP2; scripts/table-modules.json is the machine-read source).
  id  uuid  not null  default gen_random_uuid()
  org_id  uuid  not null
  user_id  uuid
