  employee_id  text
  phone  text
  status  text  not null  default 'active'::text
  created_at  timestamp with time zone  not null  default now()
  updated_at  timestamp with time zone  not null  default now()
  samsara_driver_id  text
  efs_driver_id  text
  driver_type  text
  identity_source  text  not null  default 'samsara'::text
  app_access_enabled  boolean  not null  default false
  first_name  text
  middle_name  text
  last_name  text
  date_of_birth  date
  photo_path  text
  hire_date  date
  termination_date  date
  email  text
  phone_alt  text
  address_line1  text
  address_line2  text
  city  text
  state  text
  postal_code  text
  emergency_contact_name  text
  emergency_contact_phone  text
  emergency_contact_relation  text
  cdl_number  text
  cdl_state  text
  cdl_class  text
  cdl_issued_at  date
  cdl_expires_at  date
  cdl_restrictions  text
  medical_card_expires_at  date
  medical_examiner_name  text
  medical_registry_number  text
  pay_type  text
  pay_rate  numeric
  per_diem  boolean
  settlement_company  text
  eld_id  text
  samsara_username  text
  current_hos_status  text
  current_hos_vehicle  text
  current_hos_at  timestamp with time zone
  current_location  text
  app_username  text
  app_credential_created_at  timestamp with time zone
  app_credential_reset_at  timestamp with time zone
  other_names  ARRAY
  archived_at  timestamp with time zone
  return_to_duty_required  boolean  not null  default false
  mcleod_driver_id  text
  mcleod_company_id  text
  constraint drivers_app_access_enabled_not_null: NOT NULL app_access_enabled
  constraint drivers_cdl_class_check: CHECK (((cdl_class IS NULL) OR (cdl_class = ANY (ARRAY['A'::text, 'B'::text, 'C'::text]))))
  constraint drivers_created_at_not_null: NOT NULL created_at
  constraint drivers_driver_type_check: CHECK (((driver_type IS NULL) OR (driver_type = ANY (ARRAY['company'::text, 'owner_operator'::text]))))
  constraint drivers_full_name_not_null: NOT NULL full_name
  constraint drivers_id_not_null: NOT NULL id
  constraint drivers_identity_source_check: CHECK ((identity_source = ANY (ARRAY['samsara'::text, 'manual'::text, 'efs'::text, 'mcleod'::text])))
  constraint drivers_identity_source_not_null: NOT NULL identity_source
  constraint drivers_org_id_fkey: FOREIGN KEY (org_id) REFERENCES organizations(id) ON DELETE CASCADE
  constraint drivers_org_id_not_null: NOT NULL org_id
  constraint drivers_pay_type_check: CHECK (((pay_type IS NULL) OR (pay_type = ANY (ARRAY['mileage'::text, 'hourly'::text, 'percentage'::text, 'salary'::text]))))
  constraint drivers_pkey: PRIMARY KEY (id)
  constraint drivers_return_to_duty_required_not_null: NOT NULL return_to_duty_required
  constraint drivers_status_check: CHECK ((status = ANY (ARRAY['applicant'::text, 'active'::text, 'inactive'::text, 'on_leave'::text, 'terminated'::text])))
  constraint drivers_status_not_null: NOT NULL status
  constraint drivers_updated_at_not_null: NOT NULL updated_at
  constraint drivers_user_id_fkey: FOREIGN KEY (user_id) REFERENCES auth.users(id) ON DELETE SET NULL
  index: unique index drivers_pkey on public.drivers using btree (id)
  index: unique index idx_drivers_efs_driver_id on public.drivers using btree (org_id, efs_driver_id) where (efs_driver_id is not null)
  index: index idx_drivers_org on public.drivers using btree (org_id)
  index: unique index idx_drivers_org_app_username on public.drivers using btree (org_id, lower(app_username)) where (app_username is not null)
  index: index idx_drivers_org_roster_active on public.drivers using btree (org_id, status) where (archived_at is null)
  index: unique index idx_drivers_samsara_id on public.drivers using btree (org_id, samsara_driver_id) where (samsara_driver_id is not null)
  index: unique index idx_drivers_user on public.drivers using btree (user_id) where (user_id is not null)
  index: unique index uq_drivers_org_efs on public.drivers using btree (org_id, efs_driver_id) where (efs_driver_id is not null)
  index: unique index uq_drivers_org_mcleod on public.drivers using btree (org_id, mcleod_driver_id) where (mcleod_driver_id is not null)
  index: unique index uq_drivers_org_samsara on public.drivers using btree (org_id, samsara_driver_id) where (samsara_driver_id is not null)
  policy drivers_driver_insert [RESTRICTIVE/INSERT] roles=["public"] using=- check=(auth_role() <> 'driver'::text)
  policy drivers_driver_scope [RESTRICTIVE/SELECT] roles=["public"] using=((auth_role() <> 'driver'::text) OR (id = auth_driver_id())) check=-
  policy drivers_select [PERMISSIVE/SELECT] roles=["public"] using=(org_id = auth_org_id()) check=-
  policy drivers_write [PERMISSIVE/ALL] roles=["public"] using=((org_id = auth_org_id()) AND (auth_role() = ANY (ARRAY['admin'::text, 'fleet_manager'::text, 'safety_manager'::text, 'recruiter'::text]))) check=((org_id = auth_org_id()) AND (auth_role() = ANY (ARRAY['admin'::text, 'fleet_manager'::text, 'safety_manager'::text, 'recruiter'::text])))
  trigger: create trigger audit_drivers after insert or delete or update on public.drivers for each row execute function audit_row_change('driver')
  trigger: create trigger trg_claim_driver_identity before insert or update on public.drivers for each row execute function claim_identity_for_office('full_name', 'first_name', 'middle_name', 'last_name', 'phone')
  trigger: create trigger trg_drivers_org_immutable before update on public.drivers for each row execute function forbid_org_change()
  trigger: create trigger trg_drivers_updated before update on public.drivers for each row execute function set_updated_at()
  trigger: create trigger trg_guard_driver_archive_writer before update on public.drivers for each row execute function guard_driver_archive_writer()
  trigger: create trigger trg_guard_driver_hard_delete before delete on public.drivers for each row execute function guard_driver_hard_delete()
  trigger: create trigger trg_guard_driver_lifecycle before update on public.drivers for each row execute function guard_driver_lifecycle()

-- ============================================================================
-- table duty_equipment_segments  [RLS]
--   module=driver-app; layer=core (0265, D-SEP2; scripts/table-modules.json is the machine-read
--   source).
  id  uuid  not null
  org_id  uuid  not null
  session_id  uuid  not null
  vehicle_id  uuid  not null
  trailer_id  uuid
  seat  text  not null  default 'driver'::text
  from_at  timestamp with time zone  not null  default now()
  to_at  timestamp with time zone
  confirmed_by  text  not null  default 'driver'::text
  note  text
  created_at  timestamp with time zone  not null  default now()
  updated_at  timestamp with time zone  not null  default now()
  constraint duty_confirmed_by_check: CHECK ((confirmed_by = ANY (ARRAY['driver'::text, 'dispatch'::text])))
  constraint duty_equipment_segments_check: CHECK (((to_at IS NULL) OR (to_at >= from_at)))
  constraint duty_equipment_segments_confirmed_by_not_null: NOT NULL confirmed_by
  constraint duty_equipment_segments_created_at_not_null: NOT NULL created_at
  constraint duty_equipment_segments_from_at_not_null: NOT NULL from_at
  constraint duty_equipment_segments_id_not_null: NOT NULL id
  constraint duty_equipment_segments_org_id_fkey: FOREIGN KEY (org_id) REFERENCES organizations(id) ON DELETE CASCADE
  constraint duty_equipment_segments_org_id_not_null: NOT NULL org_id
  constraint duty_equipment_segments_pkey: PRIMARY KEY (id)
  constraint duty_equipment_segments_seat_not_null: NOT NULL seat
  constraint duty_equipment_segments_session_id_fkey: FOREIGN KEY (session_id) REFERENCES driver_duty_sessions(id) ON DELETE CASCADE
  constraint duty_equipment_segments_session_id_not_null: NOT NULL session_id
  constraint duty_equipment_segments_trailer_id_fkey: FOREIGN KEY (trailer_id) REFERENCES trailers(id) ON DELETE SET NULL
  constraint duty_equipment_segments_updated_at_not_null: NOT NULL updated_at
  constraint duty_equipment_segments_vehicle_id_fkey: FOREIGN KEY (vehicle_id) REFERENCES vehicles(id) ON DELETE RESTRICT
  constraint duty_equipment_segments_vehicle_id_not_null: NOT NULL vehicle_id
  constraint duty_seat_check: CHECK ((seat = ANY (ARRAY['driver'::text, 'co_driver'::text])))
  index: unique index duty_equipment_segments_pkey on public.duty_equipment_segments using btree (id)
  index: unique index idx_duty_segments_one_driver_per_vehicle on public.duty_equipment_segments using btree (vehicle_id) where ((to_at is null) and (seat = 'driver'::text))
  index: unique index idx_duty_segments_one_holder_per_trailer on public.duty_equipment_segments using btree (trailer_id) where ((to_at is null) and (trailer_id is not null))
  index: index idx_duty_segments_org_from on public.duty_equipment_segments using btree (org_id, from_at desc)
  index: index idx_duty_segments_session_from on public.duty_equipment_segments using btree (session_id, from_at desc)
  index: index idx_duty_segments_vehicle_from on public.duty_equipment_segments using btree (vehicle_id, from_at desc)
  policy duty_segments_driver_no_update [RESTRICTIVE/UPDATE] roles=["public"] using=(auth_role() <> 'driver'::text) check=-
  policy duty_segments_driver_no_write [RESTRICTIVE/INSERT] roles=["public"] using=- check=(auth_role() <> 'driver'::text)
  policy duty_segments_driver_scope [RESTRICTIVE/SELECT] roles=["public"] using=((auth_role() <> 'driver'::text) OR (EXISTS ( SELECT 1
   FROM driver_duty_sessions s
  WHERE ((s.id = duty_equipment_segments.session_id) AND (s.driver_id = auth_driver_id()))))) check=-
  policy duty_segments_manager_write [PERMISSIVE/ALL] roles=["public"] using=((org_id = auth_org_id()) AND (auth_role() = ANY (ARRAY['admin'::text, 'fleet_manager'::text, 'dispatcher'::text]))) check=((org_id = auth_org_id()) AND (auth_role() = ANY (ARRAY['admin'::text, 'fleet_manager'::text, 'dispatcher'::text])))
  policy duty_segments_select [PERMISSIVE/SELECT] roles=["public"] using=(org_id = auth_org_id()) check=-
  trigger: create trigger trg_duty_equipment_segments_org_immutable before update on public.duty_equipment_segments for each row execute function forbid_org_change()
  trigger: create trigger trg_duty_equipment_segments_updated before update on public.duty_equipment_segments for each row execute function set_duty_equipment_segment_updated_at()
  trigger: create trigger trg_duty_segments_updated before update on public.duty_equipment_segments for each row execute function set_updated_at()

-- ============================================================================
-- table efs_capability_promotions  [RLS]
--   Which capability a person has allowed on which org, and the proof they cited. One row per org
--   per capability. Read on every card write with no cache, so that suspension takes effect on the
--   next call. Service-role only.
  id  uuid  not null  default gen_random_uuid()
  org_id  uuid  not null
  capability_key  text  not null
  state  text  not null  default 'not_promoted'::text
  proof_id  uuid
  promoted_by  uuid
  promoted_at  timestamp with time zone
  reason  text
  suspended_reason  text
  created_at  timestamp with time zone  not null  default now()
  updated_at  timestamp with time zone  not null  default now()
  constraint efs_capability_promotions_capability_key_check: CHECK (((length(btrim(capability_key)) >= 1) AND (length(btrim(capability_key)) <= 100)))
  constraint efs_capability_promotions_capability_key_not_null: NOT NULL capability_key
  constraint efs_capability_promotions_created_at_not_null: NOT NULL created_at
  constraint efs_capability_promotions_id_not_null: NOT NULL id
  constraint efs_capability_promotions_org_id_fkey: FOREIGN KEY (org_id) REFERENCES organizations(id) ON DELETE CASCADE
  constraint efs_capability_promotions_org_id_not_null: NOT NULL org_id
  constraint efs_capability_promotions_pkey: PRIMARY KEY (id)
  constraint efs_capability_promotions_promoted_by_fkey: FOREIGN KEY (promoted_by) REFERENCES auth.users(id) ON DELETE SET NULL
  constraint efs_capability_promotions_proof_id_fkey: FOREIGN KEY (proof_id) REFERENCES efs_capability_proofs(id) ON DELETE SET NULL
  constraint efs_capability_promotions_reason_check: CHECK (((reason IS NULL) OR ((length(btrim(reason)) >= 3) AND (length(btrim(reason)) <= 500))))
  constraint efs_capability_promotions_state_check: CHECK ((state = ANY (ARRAY['not_promoted'::text, 'proving'::text, 'proven'::text, 'denied'::text, 'enabled'::text, 'suspended'::text])))
  constraint efs_capability_promotions_state_not_null: NOT NULL state
  constraint efs_capability_promotions_updated_at_not_null: NOT NULL updated_at
  index: unique index efs_capability_promotions_pkey on public.efs_capability_promotions using btree (id)
  index: unique index uq_efs_capability_promotions_org_capability on public.efs_capability_promotions using btree (org_id, capability_key)

-- ============================================================================
-- table efs_capability_proofs  [RLS]
--   Immutable evidence from one live capability proof run: the OEG results, the environment it was
--   taken against, and the vendor bytes. Never rewritten — a proof is what happened, not what is
--   currently true. Service-role only.
  id  uuid  not null  default gen_random_uuid()
  org_id  uuid  not null
  capability_key  text  not null
  oeg1_entitled  boolean
  oeg2b_noop_stable  boolean
  oeg3_change_landed  boolean
  oeg4_vocabulary  boolean
  oeg5_revert_landed  boolean
  apply_latency_ms  integer
  endpoint_host  text
  environment  text
  document_shape  text
  vocabulary  jsonb
  request_xml_redacted  text
  response_xml_redacted  text
  card_last4  text
  outcome  text  not null  default 'running'::text
  outcome_detail  text
  run_by  uuid
  run_at  timestamp with time zone  not null  default now()
  completed_at  timestamp with time zone
  constraint efs_capability_proofs_apply_latency_ms_check: CHECK (((apply_latency_ms IS NULL) OR (apply_latency_ms >= 0)))
  constraint efs_capability_proofs_capability_key_check: CHECK (((length(btrim(capability_key)) >= 1) AND (length(btrim(capability_key)) <= 100)))
  constraint efs_capability_proofs_capability_key_not_null: NOT NULL capability_key
  constraint efs_capability_proofs_card_last4_check: CHECK (((card_last4 IS NULL) OR (card_last4 ~ '^[0-9]{4}$'::text)))
  constraint efs_capability_proofs_environment_check: CHECK (((environment IS NULL) OR (environment = ANY (ARRAY['sandbox'::text, 'production'::text]))))
  constraint efs_capability_proofs_id_not_null: NOT NULL id
  constraint efs_capability_proofs_org_id_fkey: FOREIGN KEY (org_id) REFERENCES organizations(id) ON DELETE CASCADE
  constraint efs_capability_proofs_org_id_not_null: NOT NULL org_id
  constraint efs_capability_proofs_outcome_check: CHECK ((outcome = ANY (ARRAY['running'::text, 'proven'::text, 'denied'::text, 'void'::text, 'error'::text])))
  constraint efs_capability_proofs_outcome_not_null: NOT NULL outcome
  constraint efs_capability_proofs_pkey: PRIMARY KEY (id)
  constraint efs_capability_proofs_run_at_not_null: NOT NULL run_at
  constraint efs_capability_proofs_run_by_fkey: FOREIGN KEY (run_by) REFERENCES auth.users(id) ON DELETE SET NULL
  index: unique index efs_capability_proofs_pkey on public.efs_capability_proofs using btree (id)
  index: index idx_efs_capability_proofs_lookup on public.efs_capability_proofs using btree (org_id, capability_key, run_at desc)

-- ============================================================================
-- table efs_card_control_approvers  [RLS]
--   module=efs; layer=core (0265, D-SEP2; scripts/table-modules.json is the machine-read source).
  org_id  uuid  not null
  user_id  uuid  not null
  scopes  ARRAY  not null  default ARRAY['lock'::text, 'unlock'::text, 'deactivate'::text, 'override'::text, 'prompts'::text]
  granted_by  uuid
  granted_at  timestamp with time zone  not null  default now()
  constraint efs_card_control_approver_scopes_valid: CHECK (((scopes <@ ARRAY['lock'::text, 'unlock'::text, 'deactivate'::text, 'override'::text, 'prompts'::text]) AND (cardinality(scopes) >= 1)))
  constraint efs_card_control_approvers_granted_at_not_null: NOT NULL granted_at
  constraint efs_card_control_approvers_granted_by_fkey: FOREIGN KEY (granted_by) REFERENCES auth.users(id) ON DELETE SET NULL
  constraint efs_card_control_approvers_org_id_fkey: FOREIGN KEY (org_id) REFERENCES organizations(id) ON DELETE CASCADE
  constraint efs_card_control_approvers_org_id_not_null: NOT NULL org_id
  constraint efs_card_control_approvers_pkey: PRIMARY KEY (org_id, user_id)
  constraint efs_card_control_approvers_scopes_not_null: NOT NULL scopes
  constraint efs_card_control_approvers_user_id_fkey: FOREIGN KEY (user_id) REFERENCES auth.users(id) ON DELETE CASCADE
  constraint efs_card_control_approvers_user_id_not_null: NOT NULL user_id
  index: unique index efs_card_control_approvers_pkey on public.efs_card_control_approvers using btree (org_id, user_id)
  index: index idx_efs_card_approvers_user on public.efs_card_control_approvers using btree (user_id)

-- ============================================================================
-- table efs_card_control_settings  [RLS]
--   module=efs; layer=core (0265, D-SEP2; scripts/table-modules.json is the machine-read source).
  org_id  uuid  not null
  enabled  boolean  not null  default false
  write_entitlement  text  not null  default 'unknown'::text
  probe_result  jsonb
  probed_at  timestamp with time zone
  probed_by  uuid
  require_approver  boolean  not null  default true
  created_at  timestamp with time zone  not null  default now()
  updated_at  timestamp with time zone  not null  default now()
  probed_endpoint_host  text
  probed_identity_hash  text
  probed_document_shape  text
  observed_document_shape  text
  observed_vocabulary  jsonb
  prompt_types  ARRAY
  prompt_types_at  timestamp with time zone
  product_groups  jsonb
  product_groups_at  timestamp with time zone
  constraint efs_card_control_settings_confirmed_requires_identity: CHECK (((write_entitlement <> 'confirmed'::text) OR (probed_identity_hash IS NOT NULL)))
  constraint efs_card_control_settings_created_at_not_null: NOT NULL created_at
  constraint efs_card_control_settings_enabled_not_null: NOT NULL enabled
  constraint efs_card_control_settings_org_id_fkey: FOREIGN KEY (org_id) REFERENCES organizations(id) ON DELETE CASCADE
  constraint efs_card_control_settings_org_id_not_null: NOT NULL org_id
  constraint efs_card_control_settings_pkey: PRIMARY KEY (org_id)
  constraint efs_card_control_settings_probed_by_fkey: FOREIGN KEY (probed_by) REFERENCES auth.users(id) ON DELETE SET NULL
  constraint efs_card_control_settings_product_groups_dated: CHECK (((product_groups IS NULL) = (product_groups_at IS NULL)))
  constraint efs_card_control_settings_product_groups_non_empty: CHECK (((product_groups IS NULL) OR ((jsonb_typeof(product_groups) = 'array'::text) AND (jsonb_array_length(product_groups) >= 1))))
  constraint efs_card_control_settings_prompt_types_dated: CHECK (((prompt_types IS NULL) = (prompt_types_at IS NULL)))
  constraint efs_card_control_settings_prompt_types_non_empty: CHECK (((prompt_types IS NULL) OR (cardinality(prompt_types) >= 1)))
  constraint efs_card_control_settings_require_approver_not_null: NOT NULL require_approver
  constraint efs_card_control_settings_updated_at_not_null: NOT NULL updated_at
  constraint efs_card_control_settings_write_entitlement_check: CHECK ((write_entitlement = ANY (ARRAY['unknown'::text, 'confirmed'::text, 'denied'::text])))
  constraint efs_card_control_settings_write_entitlement_not_null: NOT NULL write_entitlement
  index: unique index efs_card_control_settings_pkey on public.efs_card_control_settings using btree (org_id)
  trigger: create trigger trg_efs_card_control_settings_updated before update on public.efs_card_control_settings for each row execute function set_updated_at()

-- ============================================================================
-- table efs_card_mutations  [RLS]
--   Every attempted change to an EFS fuel card: intent, reason, who, the before/after card
--   documents, the redacted request/response XML and the reconciled outcome. Written pending BEFORE
--   dispatch so a crash leaves evidence rather than silence. Service-role only (RLS deny-all).
  id  uuid  not null  default gen_random_uuid()
  org_id  uuid  not null
  efs_card_id  uuid  not null
  intent  text  not null
  status  text  not null  default 'pending'::text
  reason  text  default ''::text
  requested_by  uuid
  approved_by  uuid
  step_up  boolean  not null  default false
  expected_version  text
  before_version  text
  after_version  text
  reconciled_version  text
  before_document  jsonb
  after_document  jsonb
  edits  jsonb
  drift  jsonb
  request_xml_redacted  text
  response_xml_redacted  text
  efs_fault_code  text
  efs_fault_message  text
  idempotency_key  text
  attempts  integer  not null  default 0
  created_at  timestamp with time zone  not null  default now()
  completed_at  timestamp with time zone
  updated_at  timestamp with time zone  not null  default now()
  request_fingerprint  text
  environment  text
  endpoint_host  text
  card_last4  text
  capability_key  text
  request_body  jsonb
  step_index  integer
  proof_run_id  uuid
  constraint efs_card_mutations_approved_by_fkey: FOREIGN KEY (approved_by) REFERENCES auth.users(id) ON DELETE SET NULL
  constraint efs_card_mutations_attempts_check: CHECK ((attempts >= 0))
  constraint efs_card_mutations_attempts_not_null: NOT NULL attempts
  constraint efs_card_mutations_created_at_not_null: NOT NULL created_at
  constraint efs_card_mutations_efs_card_id_fkey: FOREIGN KEY (efs_card_id) REFERENCES efs_cards(id) ON DELETE CASCADE
  constraint efs_card_mutations_efs_card_id_not_null: NOT NULL efs_card_id
  constraint efs_card_mutations_id_not_null: NOT NULL id
  constraint efs_card_mutations_intent_check: CHECK ((intent = ANY (ARRAY['lock'::text, 'unlock'::text, 'deactivate'::text, 'override_grant'::text, 'override_clear'::text, 'prompts_set'::text])))
  constraint efs_card_mutations_intent_not_null: NOT NULL intent
  constraint efs_card_mutations_org_id_fkey: FOREIGN KEY (org_id) REFERENCES organizations(id) ON DELETE CASCADE
  constraint efs_card_mutations_org_id_not_null: NOT NULL org_id
  constraint efs_card_mutations_pkey: PRIMARY KEY (id)
  constraint efs_card_mutations_proof_run_id_fkey: FOREIGN KEY (proof_run_id) REFERENCES efs_capability_proofs(id) ON DELETE SET NULL
  constraint efs_card_mutations_reason_check: CHECK (((btrim(COALESCE(reason, ''::text)) = ''::text) OR ((length(btrim(reason)) >= 3) AND (length(btrim(reason)) <= 200))))
  constraint efs_card_mutations_request_xml_len: CHECK (((request_xml_redacted IS NULL) OR (length(request_xml_redacted) <= 131072))) NOT VALID
  constraint efs_card_mutations_requested_by_fkey: FOREIGN KEY (requested_by) REFERENCES auth.users(id) ON DELETE SET NULL
  constraint efs_card_mutations_response_xml_len: CHECK (((response_xml_redacted IS NULL) OR (length(response_xml_redacted) <= 131072))) NOT VALID
  constraint efs_card_mutations_status_check: CHECK ((status = ANY (ARRAY['pending'::text, 'sent'::text, 'succeeded'::text, 'failed'::text, 'drift_detected'::text, 'partial'::text])))
  constraint efs_card_mutations_status_not_null: NOT NULL status
  constraint efs_card_mutations_step_up_not_null: NOT NULL step_up
  constraint efs_card_mutations_updated_at_not_null: NOT NULL updated_at
  index: unique index efs_card_mutations_pkey on public.efs_card_mutations using btree (id)
  index: index idx_efs_card_mutations_card on public.efs_card_mutations using btree (efs_card_id, created_at desc)
  index: index idx_efs_card_mutations_org on public.efs_card_mutations using btree (org_id, created_at desc)
  index: index idx_efs_card_mutations_org_real on public.efs_card_mutations using btree (org_id, created_at desc) where (proof_run_id is null)
  index: index idx_efs_card_mutations_unresolved on public.efs_card_mutations using btree (org_id, created_at desc) where (status = any (array['pending'::text, 'sent'::text]))
  index: unique index uq_efs_card_mutations_idempotency on public.efs_card_mutations using btree (org_id, idempotency_key) where (idempotency_key is not null)
  index: unique index uq_efs_card_mutations_one_pending on public.efs_card_mutations using btree (efs_card_id) where (status = 'pending'::text)
  trigger: create trigger efs_card_mutation_requires_approver before update on public.efs_card_mutations for each row execute function efs_card_mutation_requires_approver()
  trigger: create trigger trg_efs_card_mutations_updated before update on public.efs_card_mutations for each row execute function set_updated_at()

