  updated_at  timestamp with time zone  not null  default now()
  detail_synced_at  timestamp with time zone
  absent_since  timestamp with time zone
  fuel_card_link  jsonb
  constraint efs_cards_card_last4_check: CHECK ((card_last4 ~ '^[0-9]{4}$'::text))
  constraint efs_cards_card_last4_not_null: NOT NULL card_last4
  constraint efs_cards_card_number_sealed_not_null: NOT NULL card_number_sealed
  constraint efs_cards_card_ref_hmac_not_null: NOT NULL card_ref_hmac
