  constraint efs_cards_hand_enter_shape_check: CHECK (((hand_enter IS NULL) OR ((hand_enter <> ''::text) AND (length(hand_enter) <= 32))))
  constraint efs_cards_id_not_null: NOT NULL id
  constraint efs_cards_org_id_card_ref_hmac_key: UNIQUE (org_id, card_ref_hmac)
