  constraint efs_cards_org_id_not_null: NOT NULL org_id
  constraint efs_cards_override_uses_range_check: CHECK (((override_uses IS NULL) OR (override_uses >= 0)))
  constraint efs_cards_pkey: PRIMARY KEY (id)
  constraint efs_cards_policy_number_range_check: CHECK (((policy_number IS NULL) OR (policy_number >= 0)))
  constraint efs_cards_sources_shape_check: CHECK ((((info_source IS NULL) OR (length(info_source) <= 32)) AND ((limit_source IS NULL) OR (length(limit_source) <= 32)) AND ((location_source IS NULL) OR (length(location_source) <= 32)) AND ((time_source IS NULL) OR (length(time_source) <= 32))))
  constraint efs_cards_status_not_null: NOT NULL status
  constraint efs_cards_status_shape_check: CHECK (((status <> ''::text) AND (length(status) <= 32)))
  constraint efs_cards_sync_error_shape: CHECK (((sync_error IS NULL) OR ((jsonb_typeof(sync_error) = 'object'::text) AND (sync_error ?& ARRAY['code'::text, 'source'::text, 'at'::text]) AND (COALESCE(jsonb_typeof((sync_error -> 'code'::text)), ''::text) = 'string'::text) AND (COALESCE(jsonb_typeof((sync_error -> 'at'::text)), ''::text) = 'string'::text) AND (COALESCE((sync_error ->> 'source'::text), ''::text) = ANY (ARRAY['roster'::text, 'detail'::text])))))
  constraint efs_cards_synced_at_not_null: NOT NULL synced_at
  constraint efs_cards_updated_at_not_null: NOT NULL updated_at
