  index: index idx_efs_cards_org_status on public.efs_cards using btree (org_id, status)
  index: index idx_efs_cards_org_synced on public.efs_cards using btree (org_id, synced_at)
  index: index idx_efs_cards_org_unit on public.efs_cards using btree (org_id, unit_prompt) where (unit_prompt is not null)
  index: index idx_efs_cards_unlinked_reason on public.efs_cards using btree (org_id) where (fuel_card_id is null)
  trigger: create trigger trg_efs_cards_updated before update on public.efs_cards for each row execute function set_updated_at()

