  constraint employer_inquiries_contacted_on_not_null: NOT NULL contacted_on
  constraint employer_inquiries_created_at_not_null: NOT NULL created_at
  constraint employer_inquiries_created_by_fkey: FOREIGN KEY (created_by) REFERENCES auth.users(id) ON DELETE SET NULL
  constraint employer_inquiries_driver_id_fkey: FOREIGN KEY (driver_id) REFERENCES drivers(id) ON DELETE CASCADE
