  constraint employer_inquiries_employer_name_not_null: NOT NULL employer_name
  constraint employer_inquiries_employment_id_fkey: FOREIGN KEY (employment_id) REFERENCES driver_employment_history(id) ON DELETE CASCADE
  constraint employer_inquiries_employment_id_not_null: NOT NULL employment_id
  constraint employer_inquiries_id_not_null: NOT NULL id
  constraint employer_inquiries_kind_check: CHECK ((kind = ANY (ARRAY['safety_performance'::text, 'drug_alcohol'::text])))
  constraint employer_inquiries_kind_not_null: NOT NULL kind
  constraint employer_inquiries_method_check: CHECK ((method = ANY (ARRAY['email'::text, 'post'::text, 'fax'::text, 'phone'::text, 'portal'::text])))
  constraint employer_inquiries_method_not_null: NOT NULL method
  constraint employer_inquiries_org_id_fkey: FOREIGN KEY (org_id) REFERENCES organizations(id) ON DELETE CASCADE
  constraint employer_inquiries_org_id_not_null: NOT NULL org_id
  constraint employer_inquiries_outcome_check: CHECK ((outcome = ANY (ARRAY['awaiting'::text, 'responded'::text, 'no_response'::text, 'undeliverable'::text])))
  constraint employer_inquiries_outcome_not_null: NOT NULL outcome
  constraint employer_inquiries_pkey: PRIMARY KEY (id)
  constraint employer_inquiries_sent_to_not_null: NOT NULL sent_to
  constraint employer_inquiries_wording_version_not_null: NOT NULL wording_version
  index: index employer_inquiries_driver_idx on public.employer_inquiries using btree (org_id, driver_id, contacted_on desc)
  index: index employer_inquiries_employment_idx on public.employer_inquiries using btree (employment_id, contacted_on desc)
  index: unique index employer_inquiries_pkey on public.employer_inquiries using btree (id)
  policy employer_inquiries_read [PERMISSIVE/SELECT] roles=["public"] using=((org_id = auth_org_id()) AND (auth_role() = ANY (ARRAY['admin'::text, 'safety_manager'::text, 'recruiter'::text]))) check=-
  trigger: create trigger trg_guard_employer_inquiry before update on public.employer_inquiries for each row execute function guard_employer_inquiry_immutable()

