  policy hazmat_loads_manager_insert [PERMISSIVE/INSERT] roles=["public"] using=- check=((org_id = auth_org_id()) AND (auth_role() = ANY (ARRAY['admin'::text, 'fleet_manager'::text, 'dispatcher'::text])))
