  constraint idle_park_sessions_equipment_counts_check: CHECK (((ambient_sample_count >= 0) AND (ambient_known_idle_sec >= 0) AND (ambient_unknown_idle_sec >= 0) AND (envelope_inside_sec >= 0) AND (envelope_outside_sec >= 0) AND (envelope_ambiguous_sec >= 0) AND (((envelope_inside_sec + envelope_outside_sec) + envelope_ambiguous_sec) <= duration_sec)))
