  constraint idle_park_sessions_hos_covered_sec_not_null: NOT NULL hos_covered_sec
  constraint idle_park_sessions_hos_driving_sec_not_null: NOT NULL hos_driving_sec
  constraint idle_park_sessions_hos_evidence_status_not_null: NOT NULL hos_evidence_status
