  constraint idle_park_sessions_id_not_null: NOT NULL id
  constraint idle_park_sessions_idle_sec_not_null: NOT NULL idle_sec
  constraint idle_park_sessions_latlng_check: CHECK ((((lat IS NULL) AND (lng IS NULL)) OR (((lat >= ('-90'::integer)::numeric) AND (lat <= (90)::numeric)) AND ((lng >= ('-180'::integer)::numeric) AND (lng <= (180)::numeric)))))
