  evidence_document_id  uuid
  effective_from  date  not null
  effective_to  date
  notes  text
  created_at  timestamp with time zone  not null  default now()
  created_by  uuid
  updated_at  timestamp with time zone  not null  default now()
  constraint maintenance_inspectors_address_check: CHECK ((length(address) <= 400))
  constraint maintenance_inspectors_brake_qualified_not_null: NOT NULL brake_qualified
  constraint maintenance_inspectors_created_at_not_null: NOT NULL created_at
  constraint maintenance_inspectors_created_by_fkey: FOREIGN KEY (created_by) REFERENCES auth.users(id) ON DELETE SET NULL
  constraint maintenance_inspectors_effective_from_not_null: NOT NULL effective_from
  constraint maintenance_inspectors_evidence_document_id_fkey: FOREIGN KEY (evidence_document_id) REFERENCES documents(id) ON DELETE SET NULL
  constraint maintenance_inspectors_full_name_check: CHECK (((length(btrim(full_name)) >= 1) AND (length(btrim(full_name)) <= 200)))
  constraint maintenance_inspectors_full_name_not_null: NOT NULL full_name
  constraint maintenance_inspectors_id_not_null: NOT NULL id
  constraint maintenance_inspectors_notes_check: CHECK ((length(notes) <= 2000))
  constraint maintenance_inspectors_org_id_fkey: FOREIGN KEY (org_id) REFERENCES organizations(id) ON DELETE CASCADE
  constraint maintenance_inspectors_org_id_not_null: NOT NULL org_id
  constraint maintenance_inspectors_period: CHECK (((effective_to IS NULL) OR (effective_to >= effective_from)))
  constraint maintenance_inspectors_pkey: PRIMARY KEY (id)
  constraint maintenance_inspectors_qualification_basis_check: CHECK ((qualification_basis = ANY (ARRAY['state_federal_program'::text, 'training_and_experience'::text])))
  constraint maintenance_inspectors_qualification_basis_not_null: NOT NULL qualification_basis
  constraint maintenance_inspectors_updated_at_not_null: NOT NULL updated_at
  constraint maintenance_inspectors_user_id_fkey: FOREIGN KEY (user_id) REFERENCES auth.users(id) ON DELETE SET NULL
  index: index maintenance_inspectors_org_idx on public.maintenance_inspectors using btree (org_id, effective_to nulls first, full_name)
  index: unique index maintenance_inspectors_pkey on public.maintenance_inspectors using btree (id)
  policy maintenance_inspectors_select [PERMISSIVE/SELECT] roles=["public"] using=((org_id = auth_org_id()) AND (auth_role() = ANY (ARRAY['admin'::text, 'fleet_manager'::text, 'technician'::text, 'auditor'::text, 'accountant'::text]))) check=-
  policy maintenance_inspectors_write [PERMISSIVE/ALL] roles=["public"] using=((org_id = auth_org_id()) AND (auth_role() = ANY (ARRAY['admin'::text, 'fleet_manager'::text, 'technician'::text]))) check=((org_id = auth_org_id()) AND (auth_role() = ANY (ARRAY['admin'::text, 'fleet_manager'::text, 'technician'::text])))
