  constraint maintenance_print_profiles_layout_key_not_null: NOT NULL layout_key
  constraint maintenance_print_profiles_name_check: CHECK (((length(btrim(name)) >= 1) AND (length(btrim(name)) <= 80)))
  constraint maintenance_print_profiles_name_not_null: NOT NULL name
  constraint maintenance_print_profiles_name_unique: UNIQUE (org_id, name)
  constraint maintenance_print_profiles_notes_check: CHECK ((length(notes) <= 500))
  constraint maintenance_print_profiles_offset_x_pt_check: CHECK (((offset_x_pt >= ('-72'::integer)::numeric) AND (offset_x_pt <= (72)::numeric)))
  constraint maintenance_print_profiles_offset_x_pt_not_null: NOT NULL offset_x_pt
  constraint maintenance_print_profiles_offset_y_pt_check: CHECK (((offset_y_pt >= ('-72'::integer)::numeric) AND (offset_y_pt <= (72)::numeric)))
