  constraint maintenance_print_profiles_pkey: PRIMARY KEY (id)
  constraint maintenance_print_profiles_updated_at_not_null: NOT NULL updated_at
  index: unique index maintenance_print_profiles_name_unique on public.maintenance_print_profiles using btree (org_id, name)
  index: index maintenance_print_profiles_org_idx on public.maintenance_print_profiles using btree (org_id, name)
  index: unique index maintenance_print_profiles_pkey on public.maintenance_print_profiles using btree (id)
