-- ============================================================================
-- table saved_views  [RLS]
--   A named query string per reader per table (D-ROS14). Not evidence: rows are the reader's to
--   delete.
  user_id  uuid  not null
  org_id  uuid  not null
  table_id  text  not null
  name  text  not null
  query  text  not null
  created_at  timestamp with time zone  not null  default now()
  updated_at  timestamp with time zone  not null  default now()
  constraint saved_views_created_at_not_null: NOT NULL created_at
  constraint saved_views_name_check: CHECK (((length(btrim(name)) >= 1) AND (length(btrim(name)) <= 60)))
  constraint saved_views_name_not_null: NOT NULL name
  constraint saved_views_org_id_fkey: FOREIGN KEY (org_id) REFERENCES organizations(id) ON DELETE CASCADE
  constraint saved_views_org_id_not_null: NOT NULL org_id
  constraint saved_views_pkey: PRIMARY KEY (user_id, table_id, name)
  constraint saved_views_query_check: CHECK ((length(query) <= 2000))
  constraint saved_views_query_not_null: NOT NULL query
  constraint saved_views_table_id_check: CHECK ((table_id = 'roster.drivers'::text))
  constraint saved_views_table_id_not_null: NOT NULL table_id
  constraint saved_views_updated_at_not_null: NOT NULL updated_at
  constraint saved_views_user_id_fkey: FOREIGN KEY (user_id) REFERENCES auth.users(id) ON DELETE CASCADE
  constraint saved_views_user_id_not_null: NOT NULL user_id
  index: unique index saved_views_pkey on public.saved_views using btree (user_id, table_id, name)
  index: index saved_views_user_table_idx on public.saved_views using btree (user_id, table_id, updated_at desc)
  policy saved_views_own [PERMISSIVE/ALL] roles=["public"] using=((org_id = auth_org_id()) AND (user_id = auth_user_id())) check=((org_id = auth_org_id()) AND (user_id = auth_user_id()))
  trigger: create trigger trg_saved_views_org_immutable before update on public.saved_views for each row execute function forbid_org_change()

-- ============================================================================
-- table scoring_attempts  [RLS]
--   Durable scoring persistence attempts. A succeeded attempt is an idempotency record for the
--   atomic scoring RPC; failed attempts preserve the error for operations.
  id  uuid  not null
  org_id  uuid  not null
  transaction_id  uuid  not null
  engine_version  text  not null
  result_hash  text  not null
  status  text  not null  default 'running'::text
  error  text
  started_at  timestamp with time zone  not null  default now()
  completed_at  timestamp with time zone
  created_at  timestamp with time zone  not null  default now()
  updated_at  timestamp with time zone  not null  default now()
  constraint scoring_attempts_created_at_not_null: NOT NULL created_at
  constraint scoring_attempts_engine_version_not_null: NOT NULL engine_version
  constraint scoring_attempts_id_not_null: NOT NULL id
  constraint scoring_attempts_org_id_fkey: FOREIGN KEY (org_id) REFERENCES organizations(id) ON DELETE CASCADE
  constraint scoring_attempts_org_id_not_null: NOT NULL org_id
  constraint scoring_attempts_pkey: PRIMARY KEY (id)
  constraint scoring_attempts_result_hash_not_null: NOT NULL result_hash
  constraint scoring_attempts_started_at_not_null: NOT NULL started_at
  constraint scoring_attempts_status_check: CHECK ((status = ANY (ARRAY['running'::text, 'succeeded'::text, 'failed'::text])))
  constraint scoring_attempts_status_not_null: NOT NULL status
  constraint scoring_attempts_transaction_id_fkey: FOREIGN KEY (transaction_id) REFERENCES fuel_transactions(id) ON DELETE CASCADE
  constraint scoring_attempts_transaction_id_not_null: NOT NULL transaction_id
  constraint scoring_attempts_updated_at_not_null: NOT NULL updated_at
  index: index idx_scoring_attempts_org_started on public.scoring_attempts using btree (org_id, started_at desc)
  index: index idx_scoring_attempts_transaction_started on public.scoring_attempts using btree (transaction_id, started_at desc)
  index: unique index scoring_attempts_pkey on public.scoring_attempts using btree (id)
  policy scoring_attempts_select [PERMISSIVE/SELECT] roles=["public"] using=(org_id = auth_org_id()) check=-
  trigger: create trigger trg_scoring_attempts_org_immutable before update on public.scoring_attempts for each row execute function forbid_org_change()
  trigger: create trigger trg_scoring_attempts_updated before update on public.scoring_attempts for each row execute function set_updated_at()

-- ============================================================================
-- table seven_day_statements  [RLS]
--   The §395.8(j)(2) seven-day work statement, obtained at the HIRE rather than with the application
--   because the regulation counts the seven days before work BEGINS (D-PKT7). Immutable on UPDATE —
--   a signed statement nobody can edit — and prunable on DELETE, because §395.8(k)(1) asks for six
--   months and not for ever. Deliberately NOT in RETENTION_FORBIDDEN.
  id  uuid  not null  default gen_random_uuid()
  org_id  uuid  not null
  driver_id  uuid  not null
  statement_date  date  not null
  days  jsonb  not null
  last_relieved_at  timestamp with time zone  not null
  signed_name  text  not null
  signed_on  date  not null
  recorded_by  uuid
  created_at  timestamp with time zone  not null  default now()
  constraint seven_day_statements_created_at_not_null: NOT NULL created_at
  constraint seven_day_statements_days_not_null: NOT NULL days
  constraint seven_day_statements_days_shape: CHECK (((jsonb_typeof(days) = 'array'::text) AND (jsonb_array_length(days) = 7)))
  constraint seven_day_statements_driver_id_fkey: FOREIGN KEY (driver_id) REFERENCES drivers(id) ON DELETE CASCADE
  constraint seven_day_statements_driver_id_not_null: NOT NULL driver_id
  constraint seven_day_statements_id_not_null: NOT NULL id
  constraint seven_day_statements_last_relieved_at_not_null: NOT NULL last_relieved_at
  constraint seven_day_statements_org_id_fkey: FOREIGN KEY (org_id) REFERENCES organizations(id) ON DELETE CASCADE
  constraint seven_day_statements_org_id_not_null: NOT NULL org_id
  constraint seven_day_statements_pkey: PRIMARY KEY (id)
  constraint seven_day_statements_recorded_by_fkey: FOREIGN KEY (recorded_by) REFERENCES auth.users(id) ON DELETE SET NULL
  constraint seven_day_statements_signed_name_check: CHECK ((length(btrim(signed_name)) > 0))
  constraint seven_day_statements_signed_name_not_null: NOT NULL signed_name
  constraint seven_day_statements_signed_on_not_null: NOT NULL signed_on
  constraint seven_day_statements_statement_date_not_null: NOT NULL statement_date
  index: index idx_seven_day_statements_driver on public.seven_day_statements using btree (org_id, driver_id, statement_date desc)
  index: unique index seven_day_statements_pkey on public.seven_day_statements using btree (id)
  policy seven_day_statements_driver_scope [RESTRICTIVE/SELECT] roles=["public"] using=((auth_role() <> 'driver'::text) OR (driver_id = auth_driver_id())) check=-
  policy seven_day_statements_select [PERMISSIVE/SELECT] roles=["public"] using=(org_id = auth_org_id()) check=-
  policy seven_day_statements_write [PERMISSIVE/INSERT] roles=["public"] using=- check=((org_id = auth_org_id()) AND (auth_role() = ANY (ARRAY['admin'::text, 'fleet_manager'::text, 'safety_manager'::text])))
  trigger: create trigger trg_guard_seven_day_statement before update on public.seven_day_statements for each row execute function guard_seven_day_statement_immutable()

-- ============================================================================
-- table sms_consents  [RLS]
--   A11b/D-APP13: prior express consent to text one number about one driver's application, with the
--   exact wording agreed to. EVIDENCE — EI010-style guard (fires for the service role too) and
--   RETENTION_FORBIDDEN, because a consent that can be edited is not evidence and one pruned on a
--   schedule is a defence discarded while the claim is live. revoked_at is the only mutable column.
  id  uuid  not null  default gen_random_uuid()
  org_id  uuid  not null
  driver_id  uuid  not null
  phone  text  not null
  consent_text  text  not null
  consent_version  text  not null
  intent_statement  text  not null
  source  text  not null
  granted_at  timestamp with time zone  not null  default now()
  revoked_at  timestamp with time zone
  revoked_reason  text
  granted_ip  text
  granted_user_agent  text
  created_at  timestamp with time zone  not null  default now()
  constraint sms_consents_consent_text_not_null: NOT NULL consent_text
  constraint sms_consents_consent_version_not_null: NOT NULL consent_version
  constraint sms_consents_created_at_not_null: NOT NULL created_at
  constraint sms_consents_driver_id_fkey: FOREIGN KEY (driver_id) REFERENCES drivers(id) ON DELETE CASCADE
  constraint sms_consents_driver_id_not_null: NOT NULL driver_id
  constraint sms_consents_granted_at_not_null: NOT NULL granted_at
  constraint sms_consents_id_not_null: NOT NULL id
  constraint sms_consents_intent_statement_not_null: NOT NULL intent_statement
  constraint sms_consents_org_id_fkey: FOREIGN KEY (org_id) REFERENCES organizations(id) ON DELETE CASCADE
  constraint sms_consents_org_id_not_null: NOT NULL org_id
  constraint sms_consents_phone_not_null: NOT NULL phone
  constraint sms_consents_pkey: PRIMARY KEY (id)
  constraint sms_consents_source_check: CHECK ((source = ANY (ARRAY['application'::text, 'lead_form'::text, 'office'::text])))
  constraint sms_consents_source_not_null: NOT NULL source
  index: index idx_sms_consents_driver on public.sms_consents using btree (org_id, driver_id)
  index: index idx_sms_consents_live on public.sms_consents using btree (org_id, phone) where (revoked_at is null)
  index: unique index sms_consents_pkey on public.sms_consents using btree (id)
  trigger: create trigger trg_guard_sms_consent before update on public.sms_consents for each row execute function guard_sms_consent_immutable()

