  status  text  not null  default 'active'::text
  assigned_vehicle_id  uuid
  samsara_asset_id  text
  created_at  timestamp with time zone  not null  default now()
  updated_at  timestamp with time zone  not null  default now()
  is_reefer  boolean  not null  default false
  pairing_source  text
  pairing_confidence  numeric
  length_in  numeric
  identity_source  text  not null  default 'samsara'::text
  vin  text
  trailer_type  text
  length_ft  integer
  capacity_cube_ft  numeric
  capacity_weight_lb  numeric
  door_type  text
  suspension  text
  tare_weight_lb  numeric
