  height_in  numeric
  width_in  numeric
  constraint trailers_assigned_vehicle_id_fkey: FOREIGN KEY (assigned_vehicle_id) REFERENCES vehicles(id) ON DELETE SET NULL
  constraint trailers_cargo_compartments_not_null: NOT NULL cargo_compartments
