  constraint trailers_org_id_not_null: NOT NULL org_id
  constraint trailers_ownership_type_check: CHECK (((ownership_type IS NULL) OR (ownership_type = ANY (ARRAY['owned'::text, 'leased'::text, 'owner_operator'::text]))))
  constraint trailers_pkey: PRIMARY KEY (id)
  constraint trailers_reefer_tank_capacity_gal_not_null: NOT NULL reefer_tank_capacity_gal
  constraint trailers_status_not_null: NOT NULL status
  constraint trailers_trailer_type_check: CHECK (((trailer_type IS NULL) OR (trailer_type = ANY (ARRAY['dry_van'::text, 'reefer'::text, 'flatbed'::text, 'tanker'::text, 'hopper'::text, 'other'::text]))))
  constraint trailers_unit_number_not_null: NOT NULL unit_number
