-- ============================================================================
-- table truck_cost_schedules  [RLS]
  id  uuid  not null  default gen_random_uuid()
  org_id  uuid  not null
  unit_number  text  not null
  category  text  not null
  label  text  not null
  monthly_amount  numeric  not null
  effective_from  date  not null
  effective_to  date
  notes  text
  created_at  timestamp with time zone  not null  default now()
  updated_at  timestamp with time zone  not null  default now()
  constraint truck_cost_schedules_amount_positive: CHECK ((monthly_amount > (0)::numeric))
  constraint truck_cost_schedules_category_check: CHECK ((category = ANY (ARRAY['lease'::text, 'insurance'::text, 'gps'::text, 'permit'::text, 'other'::text])))
  constraint truck_cost_schedules_category_not_null: NOT NULL category
  constraint truck_cost_schedules_created_at_not_null: NOT NULL created_at
  constraint truck_cost_schedules_effective_from_not_null: NOT NULL effective_from
  constraint truck_cost_schedules_from_month_aligned: CHECK ((EXTRACT(day FROM effective_from) = (1)::numeric))
  constraint truck_cost_schedules_id_not_null: NOT NULL id
  constraint truck_cost_schedules_label_not_blank: CHECK ((length(TRIM(BOTH FROM label)) > 0))
  constraint truck_cost_schedules_label_not_null: NOT NULL label
  constraint truck_cost_schedules_monthly_amount_not_null: NOT NULL monthly_amount
  constraint truck_cost_schedules_org_id_fkey: FOREIGN KEY (org_id) REFERENCES organizations(id) ON DELETE CASCADE
  constraint truck_cost_schedules_org_id_not_null: NOT NULL org_id
  constraint truck_cost_schedules_pkey: PRIMARY KEY (id)
  constraint truck_cost_schedules_to_month_aligned: CHECK (((effective_to IS NULL) OR ((EXTRACT(day FROM effective_to) = (1)::numeric) AND (effective_to > effective_from))))
  constraint truck_cost_schedules_unit_not_blank: CHECK ((length(TRIM(BOTH FROM unit_number)) > 0))
  constraint truck_cost_schedules_unit_number_not_null: NOT NULL unit_number
  constraint truck_cost_schedules_updated_at_not_null: NOT NULL updated_at
  index: index idx_truck_cost_schedules_org_unit on public.truck_cost_schedules using btree (org_id, unit_number, effective_from)
  index: unique index truck_cost_schedules_pkey on public.truck_cost_schedules using btree (id)

-- ============================================================================
-- table vehicle_engine_days  [RLS]
--   module=idle; layer=derived (0265, D-SEP2; scripts/table-modules.json is the machine-read
--   source).
  id  uuid  not null  default gen_random_uuid()
  org_id  uuid  not null
  vehicle_id  uuid  not null
  day  date  not null
  drive_sec  integer  not null  default 0
  idle_sec  integer  not null  default 0
  off_sec  integer  not null  default 0
  coverage_sec  integer  not null  default 0
  tz_offset_minutes  integer  not null  default 0
  synced_at  timestamp with time zone  not null  default now()
  constraint vehicle_engine_days_coverage_sec_not_null: NOT NULL coverage_sec
  constraint vehicle_engine_days_day_not_null: NOT NULL day
  constraint vehicle_engine_days_drive_sec_not_null: NOT NULL drive_sec
  constraint vehicle_engine_days_id_not_null: NOT NULL id
  constraint vehicle_engine_days_idle_sec_not_null: NOT NULL idle_sec
  constraint vehicle_engine_days_off_sec_not_null: NOT NULL off_sec
  constraint vehicle_engine_days_org_id_fkey: FOREIGN KEY (org_id) REFERENCES organizations(id) ON DELETE CASCADE
  constraint vehicle_engine_days_org_id_not_null: NOT NULL org_id
  constraint vehicle_engine_days_pkey: PRIMARY KEY (id)
  constraint vehicle_engine_days_synced_at_not_null: NOT NULL synced_at
  constraint vehicle_engine_days_tz_offset_minutes_not_null: NOT NULL tz_offset_minutes
  constraint vehicle_engine_days_vehicle_id_fkey: FOREIGN KEY (vehicle_id) REFERENCES vehicles(id) ON DELETE CASCADE
  constraint vehicle_engine_days_vehicle_id_not_null: NOT NULL vehicle_id
  index: unique index idx_vehicle_engine_days_key on public.vehicle_engine_days using btree (org_id, vehicle_id, day)
  index: index idx_vehicle_engine_days_org_day on public.vehicle_engine_days using btree (org_id, day)
  index: unique index vehicle_engine_days_pkey on public.vehicle_engine_days using btree (id)
  policy vehicle_engine_days_select [PERMISSIVE/SELECT] roles=["public"] using=(org_id = auth_org_id()) check=-
  trigger: create trigger trg_vehicle_engine_days_org_immutable before update on public.vehicle_engine_days for each row execute function forbid_org_change()

-- ============================================================================
-- table vehicle_idle_learned  [RLS]
--   module=idle; layer=derived; rebuild=idle capability/evidence/envelope syncs re-derive from
--   telemetry. Idle learning per truck, mirrored from vehicles' legacy learner columns by
--   trg_vehicle_learned_satellites since 0262 (D-SEP3).
  vehicle_id  uuid  not null
  org_id  uuid  not null
  idle_capability  text
  idle_optimized_pct  numeric
  idle_states_sec  bigint
  idle_states_window_days  integer
  idle_states_at  timestamp with time zone
  idle_observed_mode  text
  idle_evidence_status  text
  idle_evidence_sessions  integer
  idle_evidence_parked_sec  bigint
  idle_evidence_state_samples  integer
  idle_evidence_gps_state_samples  integer
  idle_evidence_confidence  numeric
  idle_evidence_version  text
  idle_evidence_at  timestamp with time zone
  idle_learned_envelope_status  text
  idle_learned_envelope_low_f  numeric
  idle_learned_envelope_high_f  numeric
  idle_learned_envelope_sessions  integer
  idle_learned_envelope_known_idle_sec  integer
  idle_learned_envelope_cycling_sec  integer
  idle_learned_envelope_continuous_sec  integer
  idle_learned_envelope_temperature_bins  integer
  idle_learned_envelope_version  text
  idle_learned_envelope_at  timestamp with time zone
  updated_at  timestamp with time zone  not null  default now()
  constraint vehicle_idle_learned_org_id_fkey: FOREIGN KEY (org_id) REFERENCES organizations(id) ON DELETE CASCADE
  constraint vehicle_idle_learned_org_id_not_null: NOT NULL org_id
  constraint vehicle_idle_learned_pkey: PRIMARY KEY (vehicle_id)
  constraint vehicle_idle_learned_updated_at_not_null: NOT NULL updated_at
  constraint vehicle_idle_learned_vehicle_id_fkey: FOREIGN KEY (vehicle_id) REFERENCES vehicles(id) ON DELETE CASCADE
  constraint vehicle_idle_learned_vehicle_id_not_null: NOT NULL vehicle_id
  index: index idx_vehicle_idle_learned_org on public.vehicle_idle_learned using btree (org_id)
  index: unique index vehicle_idle_learned_pkey on public.vehicle_idle_learned using btree (vehicle_id)

-- ============================================================================
-- table vehicle_inspection_items  [RLS]
--   The §396.21(a)(5) per-component results for one report, keyed by the versioned Appendix A
--   catalogue in packages/shared/src/annualInspectionCatalogue.ts.
  id  uuid  not null  default gen_random_uuid()
  org_id  uuid  not null
  inspection_id  uuid  not null
  item_key  text  not null
  result  text  not null
  source  text  not null  default 'default'::text
  repaired_at  date
  note  text
  created_at  timestamp with time zone  not null  default now()
  updated_at  timestamp with time zone  not null  default now()
  constraint vehicle_inspection_items_created_at_not_null: NOT NULL created_at
  constraint vehicle_inspection_items_id_not_null: NOT NULL id
  constraint vehicle_inspection_items_inspection_id_fkey: FOREIGN KEY (inspection_id) REFERENCES vehicle_inspections(id) ON DELETE CASCADE
  constraint vehicle_inspection_items_inspection_id_not_null: NOT NULL inspection_id
  constraint vehicle_inspection_items_item_key_check: CHECK (((length(btrim(item_key)) >= 1) AND (length(btrim(item_key)) <= 80)))
  constraint vehicle_inspection_items_item_key_not_null: NOT NULL item_key
  constraint vehicle_inspection_items_note_check: CHECK ((length(note) <= 500))
  constraint vehicle_inspection_items_org_id_fkey: FOREIGN KEY (org_id) REFERENCES organizations(id) ON DELETE CASCADE
  constraint vehicle_inspection_items_org_id_not_null: NOT NULL org_id
  constraint vehicle_inspection_items_pkey: PRIMARY KEY (id)
  constraint vehicle_inspection_items_repair_date: CHECK (((repaired_at IS NULL) OR (result = 'needs_repair'::text)))
  constraint vehicle_inspection_items_result_check: CHECK ((result = ANY (ARRAY['ok'::text, 'needs_repair'::text, 'na'::text])))
  constraint vehicle_inspection_items_result_not_null: NOT NULL result
  constraint vehicle_inspection_items_source_check: CHECK ((source = ANY (ARRAY['default'::text, 'inspector'::text])))
  constraint vehicle_inspection_items_source_not_null: NOT NULL source
  constraint vehicle_inspection_items_unique: UNIQUE (inspection_id, item_key)
  constraint vehicle_inspection_items_updated_at_not_null: NOT NULL updated_at
  index: index vehicle_inspection_items_defects_idx on public.vehicle_inspection_items using btree (org_id, item_key) where (result = 'needs_repair'::text)
  index: index vehicle_inspection_items_inspection_idx on public.vehicle_inspection_items using btree (inspection_id)
  index: unique index vehicle_inspection_items_pkey on public.vehicle_inspection_items using btree (id)
  index: unique index vehicle_inspection_items_unique on public.vehicle_inspection_items using btree (inspection_id, item_key)
  policy vehicle_inspection_items_select [PERMISSIVE/SELECT] roles=["public"] using=((org_id = auth_org_id()) AND (auth_role() = ANY (ARRAY['admin'::text, 'fleet_manager'::text, 'technician'::text, 'auditor'::text, 'accountant'::text]))) check=-
  policy vehicle_inspection_items_write [PERMISSIVE/ALL] roles=["public"] using=((org_id = auth_org_id()) AND (auth_role() = ANY (ARRAY['admin'::text, 'fleet_manager'::text, 'technician'::text]))) check=((org_id = auth_org_id()) AND (auth_role() = ANY (ARRAY['admin'::text, 'fleet_manager'::text, 'technician'::text])))
  trigger: create trigger trg_vehicle_inspection_items_final_immutable before update on public.vehicle_inspection_items for each row execute function forbid_final_inspection_item_change()
  trigger: create trigger trg_vehicle_inspection_items_org_immutable before update on public.vehicle_inspection_items for each row execute function forbid_org_change()
  trigger: create trigger trg_vehicle_inspection_items_updated before update on public.vehicle_inspection_items for each row execute function set_updated_at()

-- ============================================================================
-- table vehicle_inspections  [RLS]
--   One §396.17 annual inspection report. Append-only once final (D-AVI4); the PDF lives in
--   documents
--   and the expiry in certifications — see the plan's §2.4 for why all three exist.
  id  uuid  not null
  org_id  uuid  not null
  subject_type  text  not null
  subject_id  uuid  not null
  inspector_id  uuid  not null
  inspected_on  date  not null
  catalogue_version  text  not null
  vehicle_identification_method  text  not null  default 'vin'::text
  vehicle_identification_value  text
  inspection_agency_location  text
  decal_serial  text
  other_conditions  text
  status  text  not null  default 'draft'::text
  outcome  text
  next_due_on  date
  supersedes_id  uuid
  certification_id  uuid
  document_id  uuid
  finalized_at  timestamp with time zone
  finalized_by  uuid
  created_at  timestamp with time zone  not null  default now()
  created_by  uuid
  updated_at  timestamp with time zone  not null  default now()
  constraint vehicle_inspections_catalogue_version_not_null: NOT NULL catalogue_version
  constraint vehicle_inspections_certification_id_fkey: FOREIGN KEY (certification_id) REFERENCES certifications(id) ON DELETE SET NULL
  constraint vehicle_inspections_created_at_not_null: NOT NULL created_at
  constraint vehicle_inspections_created_by_fkey: FOREIGN KEY (created_by) REFERENCES auth.users(id) ON DELETE SET NULL
  constraint vehicle_inspections_document_id_fkey: FOREIGN KEY (document_id) REFERENCES documents(id) ON DELETE SET NULL
  constraint vehicle_inspections_due_after: CHECK (((next_due_on IS NULL) OR (next_due_on > inspected_on)))
  constraint vehicle_inspections_finalized_by_fkey: FOREIGN KEY (finalized_by) REFERENCES auth.users(id) ON DELETE SET NULL
  constraint vehicle_inspections_id_not_null: NOT NULL id
  constraint vehicle_inspections_inspected_on_not_null: NOT NULL inspected_on
  constraint vehicle_inspections_inspection_agency_location_check: CHECK ((length(inspection_agency_location) <= 200))
  constraint vehicle_inspections_inspector_id_fkey: FOREIGN KEY (inspector_id) REFERENCES maintenance_inspectors(id) ON DELETE RESTRICT
  constraint vehicle_inspections_inspector_id_not_null: NOT NULL inspector_id
  constraint vehicle_inspections_org_id_fkey: FOREIGN KEY (org_id) REFERENCES organizations(id) ON DELETE CASCADE
  constraint vehicle_inspections_org_id_not_null: NOT NULL org_id
  constraint vehicle_inspections_other_conditions_check: CHECK ((length(other_conditions) <= 2000))
  constraint vehicle_inspections_outcome_check: CHECK ((outcome = ANY (ARRAY['pass'::text, 'fail'::text])))
  constraint vehicle_inspections_pkey: PRIMARY KEY (id)
  constraint vehicle_inspections_shape: CHECK ((((status = 'draft'::text) AND (outcome IS NULL) AND (next_due_on IS NULL) AND (finalized_at IS NULL)) OR ((status = 'final'::text) AND (outcome IS NOT NULL) AND (next_due_on IS NOT NULL) AND (finalized_at IS NOT NULL))))
  constraint vehicle_inspections_status_check: CHECK ((status = ANY (ARRAY['draft'::text, 'final'::text])))
  constraint vehicle_inspections_status_not_null: NOT NULL status
  constraint vehicle_inspections_stock_serial_check: CHECK ((length(decal_serial) <= 40))
  constraint vehicle_inspections_subject_id_not_null: NOT NULL subject_id
  constraint vehicle_inspections_subject_type_check: CHECK ((subject_type = ANY (ARRAY['tractor'::text, 'trailer'::text])))
  constraint vehicle_inspections_subject_type_not_null: NOT NULL subject_type
  constraint vehicle_inspections_supersedes_id_fkey: FOREIGN KEY (supersedes_id) REFERENCES vehicle_inspections(id) ON DELETE SET NULL
  constraint vehicle_inspections_updated_at_not_null: NOT NULL updated_at
  constraint vehicle_inspections_vehicle_identification_method_check: CHECK ((vehicle_identification_method = ANY (ARRAY['vin'::text, 'plate'::text, 'other'::text])))
  constraint vehicle_inspections_vehicle_identification_method_not_null: NOT NULL vehicle_identification_method
  constraint vehicle_inspections_vehicle_identification_value_check: CHECK ((length(vehicle_identification_value) <= 60))
  index: unique index vehicle_inspections_decal_serial_idx on public.vehicle_inspections using btree (org_id, decal_serial) where (decal_serial is not null)
  index: index vehicle_inspections_org_status_idx on public.vehicle_inspections using btree (org_id, status, inspected_on desc)
  index: unique index vehicle_inspections_pkey on public.vehicle_inspections using btree (id)
  index: index vehicle_inspections_subject_idx on public.vehicle_inspections using btree (org_id, subject_type, subject_id, inspected_on desc)
  policy vehicle_inspections_select [PERMISSIVE/SELECT] roles=["public"] using=((org_id = auth_org_id()) AND (auth_role() = ANY (ARRAY['admin'::text, 'fleet_manager'::text, 'technician'::text, 'auditor'::text, 'accountant'::text]))) check=-
  policy vehicle_inspections_write [PERMISSIVE/ALL] roles=["public"] using=((org_id = auth_org_id()) AND (auth_role() = ANY (ARRAY['admin'::text, 'fleet_manager'::text, 'technician'::text]))) check=((org_id = auth_org_id()) AND (auth_role() = ANY (ARRAY['admin'::text, 'fleet_manager'::text, 'technician'::text])))
  trigger: create trigger trg_vehicle_inspections_final_immutable before update on public.vehicle_inspections for each row when ((old.status = 'final'::text)) execute function forbid_final_inspection_change()
  trigger: create trigger trg_vehicle_inspections_org_immutable before update on public.vehicle_inspections for each row execute function forbid_org_change()
  trigger: create trigger trg_vehicle_inspections_updated before update on public.vehicle_inspections for each row execute function set_updated_at()

-- ============================================================================
-- table vehicle_tank_learned  [RLS]
--   module=anomalies; layer=derived; rebuild=scoring learners re-derive from fill history. Tank
--   calibration learned per truck, mirrored from vehicles' legacy learner columns by
--   trg_vehicle_learned_satellites since 0262 (D-SEP3).
  vehicle_id  uuid  not null
  org_id  uuid  not null
  odometer_offset  numeric
  odometer_offset_source  text
  tank_fill_ratio  numeric
  tank_sensor_reliable  boolean
  observed_max_fill_gal  numeric
  sensor_capacity_gal  numeric
  sensor_capacity_samples  integer
  tank_residual_sigma  numeric
  learned_tank_capacity_gal  numeric
  updated_at  timestamp with time zone  not null  default now()
  constraint vehicle_tank_learned_org_id_fkey: FOREIGN KEY (org_id) REFERENCES organizations(id) ON DELETE CASCADE
  constraint vehicle_tank_learned_org_id_not_null: NOT NULL org_id
  constraint vehicle_tank_learned_pkey: PRIMARY KEY (vehicle_id)
  constraint vehicle_tank_learned_updated_at_not_null: NOT NULL updated_at
  constraint vehicle_tank_learned_vehicle_id_fkey: FOREIGN KEY (vehicle_id) REFERENCES vehicles(id) ON DELETE CASCADE
  constraint vehicle_tank_learned_vehicle_id_not_null: NOT NULL vehicle_id
  index: index idx_vehicle_tank_learned_org on public.vehicle_tank_learned using btree (org_id)
  index: unique index vehicle_tank_learned_pkey on public.vehicle_tank_learned using btree (vehicle_id)

-- ============================================================================
-- table vehicles  [RLS]
--   module=roster; layer=core (0265, D-SEP2; scripts/table-modules.json is the machine-read source).
  id  uuid  not null  default gen_random_uuid()
  org_id  uuid  not null
  unit_number  text  not null
  make  text
  model  text
  year  integer
  plate  text
  vin  text
  fuel_type  USER-DEFINED  not null  default 'diesel'::fuel_type
  tank_capacity_gal  numeric  not null
  baseline_mpg  numeric
  current_odometer  numeric  not null  default 0
  status  USER-DEFINED  not null  default 'active'::vehicle_status
  assigned_driver_id  uuid
  created_at  timestamp with time zone  not null  default now()
  updated_at  timestamp with time zone  not null  default now()
  samsara_vehicle_id  text
  odometer_offset  numeric  not null  default 0
  odometer_offset_source  text  not null  default 'auto'::text
  monitored_tank_capacity_gal  numeric
  tank_sensor_reliable  boolean  not null  default false
  tank_fill_ratio  numeric
  observed_max_fill_gal  numeric
  idle_capability  text
  idle_optimized_pct  numeric
  has_apu  boolean
  apu_type  text
  has_optimized_idle  boolean
  idle_states_sec  bigint
  idle_states_window_days  integer
  idle_states_at  timestamp with time zone
  height_in  numeric
  length_in  numeric
  width_in  numeric
  axle_count  integer
  tare_weight_lb  numeric
  identity_source  text  not null  default 'samsara'::text
  ownership_type  text
  owner_driver_id  uuid
  purchased_at  date
  purchase_cost  numeric
  lienholder  text
  title_number  text
  plate_state  text
  registration_expires_at  date
  irp_account  text
  ifta_account  text
  insurance_carrier  text
  insurance_policy  text
  insurance_expires_at  date
  dot_annual_inspection_expires_at  date
  next_pm_due_odometer  numeric
  next_pm_due_at  date
  engine_make  text
  engine_model  text
  horsepower  integer
  transmission  text
  gvwr_lb  numeric
  sleeper  boolean
  eld_id  text
  sensor_capacity_gal  numeric
  sensor_capacity_samples  integer
  tank_capacity_source  text
  tank_residual_sigma  numeric
  samsara_fuel_percent  numeric
  samsara_fuel_at  timestamp with time zone
  cargo_capacity_gal  numeric
  cargo_compartments  jsonb  not null  default '[]'::jsonb
  idle_observed_mode  text  not null  default 'unknown'::text
  idle_evidence_status  text  not null  default 'insufficient'::text
  idle_evidence_sessions  integer  not null  default 0
  idle_evidence_parked_sec  bigint  not null  default 0
  idle_evidence_state_samples  integer  not null  default 0
  idle_evidence_gps_state_samples  integer  not null  default 0
  idle_evidence_confidence  numeric
  idle_evidence_version  text  not null  default 'engine-states-v1'::text
  idle_evidence_at  timestamp with time zone
  idle_learned_envelope_status  text  not null  default 'not_applicable'::text
  idle_learned_envelope_low_f  numeric
  idle_learned_envelope_high_f  numeric
  idle_learned_envelope_sessions  integer  not null  default 0
  idle_learned_envelope_known_idle_sec  integer  not null  default 0
  idle_learned_envelope_cycling_sec  integer  not null  default 0
  idle_learned_envelope_continuous_sec  integer  not null  default 0
  idle_learned_envelope_temperature_bins  integer  not null  default 0
  idle_learned_envelope_version  text
  idle_learned_envelope_at  timestamp with time zone
  samsara_missing_since  timestamp with time zone
  mcleod_tractor_id  text
  mcleod_company_id  text
  constraint vehicles_assigned_driver_id_fkey: FOREIGN KEY (assigned_driver_id) REFERENCES drivers(id) ON DELETE SET NULL
  constraint vehicles_cargo_compartments_not_null: NOT NULL cargo_compartments
  constraint vehicles_created_at_not_null: NOT NULL created_at
  constraint vehicles_current_odometer_not_null: NOT NULL current_odometer
  constraint vehicles_fuel_type_not_null: NOT NULL fuel_type
  constraint vehicles_id_not_null: NOT NULL id
  constraint vehicles_identity_source_check: CHECK ((identity_source = ANY (ARRAY['samsara'::text, 'manual'::text, 'mcleod'::text])))
  constraint vehicles_identity_source_not_null: NOT NULL identity_source
  constraint vehicles_idle_evidence_confidence_check: CHECK (((idle_evidence_confidence IS NULL) OR ((idle_evidence_confidence >= (0)::numeric) AND (idle_evidence_confidence <= (1)::numeric))))
  constraint vehicles_idle_evidence_counts_check: CHECK (((idle_evidence_sessions >= 0) AND (idle_evidence_parked_sec >= 0) AND (idle_evidence_state_samples >= 0) AND (idle_evidence_gps_state_samples >= 0)))
  constraint vehicles_idle_evidence_gps_state_samples_not_null: NOT NULL idle_evidence_gps_state_samples
  constraint vehicles_idle_evidence_parked_sec_not_null: NOT NULL idle_evidence_parked_sec
  constraint vehicles_idle_evidence_sessions_not_null: NOT NULL idle_evidence_sessions
  constraint vehicles_idle_evidence_state_samples_not_null: NOT NULL idle_evidence_state_samples
  constraint vehicles_idle_evidence_status_check: CHECK ((idle_evidence_status = ANY (ARRAY['sufficient'::text, 'insufficient'::text])))
  constraint vehicles_idle_evidence_status_not_null: NOT NULL idle_evidence_status
  constraint vehicles_idle_evidence_version_not_null: NOT NULL idle_evidence_version
  constraint vehicles_idle_learned_envelope_bounds_check: CHECK ((((idle_learned_envelope_low_f IS NULL) AND (idle_learned_envelope_high_f IS NULL)) OR ((idle_learned_envelope_low_f IS NOT NULL) AND (idle_learned_envelope_high_f IS NOT NULL) AND (idle_learned_envelope_low_f < idle_learned_envelope_high_f))))
  constraint vehicles_idle_learned_envelope_continuous_sec_not_null: NOT NULL idle_learned_envelope_continuous_sec
  constraint vehicles_idle_learned_envelope_counts_check: CHECK (((idle_learned_envelope_sessions >= 0) AND (idle_learned_envelope_known_idle_sec >= 0) AND (idle_learned_envelope_cycling_sec >= 0) AND (idle_learned_envelope_continuous_sec >= 0) AND (idle_learned_envelope_temperature_bins >= 0)))
  constraint vehicles_idle_learned_envelope_cycling_sec_not_null: NOT NULL idle_learned_envelope_cycling_sec
  constraint vehicles_idle_learned_envelope_known_idle_sec_not_null: NOT NULL idle_learned_envelope_known_idle_sec
  constraint vehicles_idle_learned_envelope_sessions_not_null: NOT NULL idle_learned_envelope_sessions
  constraint vehicles_idle_learned_envelope_status_check: CHECK ((idle_learned_envelope_status = ANY (ARRAY['sufficient'::text, 'insufficient'::text, 'not_applicable'::text])))
  constraint vehicles_idle_learned_envelope_status_not_null: NOT NULL idle_learned_envelope_status
  constraint vehicles_idle_learned_envelope_sufficient_check: CHECK (((idle_learned_envelope_status <> 'sufficient'::text) OR ((idle_learned_envelope_low_f IS NOT NULL) AND (idle_learned_envelope_high_f IS NOT NULL))))
  constraint vehicles_idle_learned_envelope_temperature_bins_not_null: NOT NULL idle_learned_envelope_temperature_bins
  constraint vehicles_idle_observed_mode_check: CHECK ((idle_observed_mode = ANY (ARRAY['continuous_main_engine'::text, 'optimized_cycling_observed'::text, 'engine_off_observed'::text, 'unknown'::text])))
  constraint vehicles_idle_observed_mode_not_null: NOT NULL idle_observed_mode
  constraint vehicles_odometer_offset_not_null: NOT NULL odometer_offset
  constraint vehicles_odometer_offset_source_not_null: NOT NULL odometer_offset_source
  constraint vehicles_org_id_fkey: FOREIGN KEY (org_id) REFERENCES organizations(id) ON DELETE CASCADE
  constraint vehicles_org_id_not_null: NOT NULL org_id
  constraint vehicles_org_id_unit_number_key: UNIQUE (org_id, unit_number)
  constraint vehicles_owner_driver_id_fkey: FOREIGN KEY (owner_driver_id) REFERENCES drivers(id) ON DELETE SET NULL
  constraint vehicles_ownership_type_check: CHECK (((ownership_type IS NULL) OR (ownership_type = ANY (ARRAY['owned'::text, 'leased'::text, 'owner_operator'::text]))))
  constraint vehicles_pkey: PRIMARY KEY (id)
  constraint vehicles_status_not_null: NOT NULL status
  constraint vehicles_tank_capacity_gal_not_null: NOT NULL tank_capacity_gal
  constraint vehicles_tank_sensor_reliable_not_null: NOT NULL tank_sensor_reliable
  constraint vehicles_unit_number_not_null: NOT NULL unit_number
  constraint vehicles_updated_at_not_null: NOT NULL updated_at
  index: index idx_vehicles_org on public.vehicles using btree (org_id)
  index: index idx_vehicles_owner_driver on public.vehicles using btree (owner_driver_id) where (owner_driver_id is not null)
  index: unique index uq_vehicles_org_mcleod on public.vehicles using btree (org_id, mcleod_tractor_id) where (mcleod_tractor_id is not null)
  index: unique index uq_vehicles_org_samsara on public.vehicles using btree (org_id, samsara_vehicle_id) where (samsara_vehicle_id is not null)
  index: unique index uq_vehicles_org_unit_active on public.vehicles using btree (org_id, unit_number) where (status = 'active'::vehicle_status)
  index: unique index uq_vehicles_org_vin on public.vehicles using btree (org_id, upper(vin)) where ((vin is not null) and (vin <> ''::text))
  index: unique index vehicles_org_id_unit_number_key on public.vehicles using btree (org_id, unit_number)
  index: unique index vehicles_pkey on public.vehicles using btree (id)
  policy vehicles_driver_insert [RESTRICTIVE/INSERT] roles=["public"] using=- check=(auth_role() <> 'driver'::text)
  policy vehicles_driver_scope [RESTRICTIVE/SELECT] roles=["public"] using=((auth_role() <> 'driver'::text) OR (assigned_driver_id = auth_driver_id()) OR (EXISTS ( SELECT 1
   FROM (duty_equipment_segments seg
     JOIN driver_duty_sessions s ON ((s.id = seg.session_id)))
  WHERE ((seg.vehicle_id = vehicles.id) AND (seg.to_at IS NULL) AND (s.driver_id = auth_driver_id()) AND (s.ended_at IS NULL))))) check=-
  policy vehicles_select [PERMISSIVE/SELECT] roles=["public"] using=(org_id = auth_org_id()) check=-
  policy vehicles_write [PERMISSIVE/ALL] roles=["public"] using=((org_id = auth_org_id()) AND (auth_role() = ANY (ARRAY['admin'::text, 'fleet_manager'::text]))) check=((org_id = auth_org_id()) AND (auth_role() = ANY (ARRAY['admin'::text, 'fleet_manager'::text])))
  trigger: create trigger audit_vehicles after insert or delete or update on public.vehicles for each row execute function audit_row_change('vehicle')
  trigger: create trigger trg_claim_vehicle_identity before insert or update on public.vehicles for each row execute function claim_identity_for_office('vin', 'make', 'model', 'year', 'plate', 'plate_state', 'registration_expires_at', 'dot_annual_inspection_expires_at', 'purchased_at')
  trigger: create trigger trg_vehicle_learned_satellites after insert or update on public.vehicles for each row execute function sync_vehicle_learned_satellites()
  trigger: create trigger trg_vehicles_org_immutable before update on public.vehicles for each row execute function forbid_org_change()
  trigger: create trigger trg_vehicles_updated before update on public.vehicles for each row execute function set_updated_at()

-- ============================================================================
-- table weather_cache  [RLS]
--   module=idle; layer=infra (0265, D-SEP2; scripts/table-modules.json is the machine-read source).
  lat_grid  numeric  not null
  lng_grid  numeric  not null
  hour_utc  timestamp with time zone  not null
  temp_f  numeric
  fetched_at  timestamp with time zone  not null  default now()
  constraint weather_cache_fetched_at_not_null: NOT NULL fetched_at
  constraint weather_cache_hour_utc_not_null: NOT NULL hour_utc
  constraint weather_cache_lat_grid_not_null: NOT NULL lat_grid
  constraint weather_cache_lng_grid_not_null: NOT NULL lng_grid
  constraint weather_cache_pkey: PRIMARY KEY (lat_grid, lng_grid, hour_utc)
  index: unique index weather_cache_pkey on public.weather_cache using btree (lat_grid, lng_grid, hour_utc)

